const items = $input.all();
const results = [];

for (const item of items) {
  let parsed;
  try {
    const raw = (item.json.output || '')
      .replace(/```json/g, '')
      .replace(/```/g, '')
      .trim();
    parsed = JSON.parse(raw);
  } catch (e) {
    parsed = {
      verdict: 'unknown',
      confidence: 0,
      indicators: [],
      reasoning: 'Failed to parse: ' + (item.json.output || 'no output')
    };
  }

  if (!parsed.source) {
    parsed.source = item.json.source || 'unknown';
  }

  // keep all fields in input（event_group、group_type、src_ips...）
  const merged = {
    ...item.json,   
    ...parsed,      
  };

  delete merged.output;

  results.push({ json: merged });
}

return results;

const raw = ($json.output || '')
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

let report;
try {
  report = JSON.parse(raw);
} catch(e) {
  return [{ json: { response: raw } }];
}

const eventId   = $json.event_id   || report.incident_id || `EVT-${Date.now()}`;
const groupType = $json.group_type || report.group_type  || 'unknown';
const srcIPs    = $json.src_ips    || 'unknown';
const dstIPs    = $json.dst_ips    || 'unknown';

const text = `
🚨 INCIDENT REPORT — ${eventId}
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
Severity    : ${report.severity}
Verdict     : ${report.verdict}
Confidence  : ${(report.confidence * 100).toFixed(0)}%
Attack Type : ${groupType}
Source IPs  : ${srcIPs}
Target IPs  : ${dstIPs}

📋 Summary
${report.summary}

🔍 Indicators of Compromise
${(report.indicators_of_compromise || []).map(i => `• ${i}`).join('\n') || '• None identified'}

📅 Correlated Timeline
${(report.correlated_timeline || []).map(t => `• ${t}`).join('\n') || '• No timeline data'}

✅ Recommended Actions
${(report.recommended_actions || []).map(a => `• ${a}`).join('\n') || '• Continue monitoring'}

🧠 Justification
${report.justification}
`.trim();

const fs = require('fs');
const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
const savePath  = `/home/node/reports/${eventId}_${timestamp}.txt`;
fs.mkdirSync('/home/node/reports', { recursive: true });
fs.writeFileSync(savePath, text, 'utf8');

return { json: {
  response:   text,
  savedPath:  savePath,
  verdict:    report.verdict   || 'unknown',
  severity:   report.severity  || 'unknown',
  incidentId: eventId,
  groupType:  groupType,
} };

const now = new Date();
const fiveMinAgo = new Date(now.getTime() - 60 * 60 * 1000);

return [{
  json: {
    from: fiveMinAgo.toISOString(),
    to: now.toISOString()
  }
}];

// ── FORMAT ZEEK NODE ─────────────────────────────────────────
// Mode: Run Once for All Items
// Aggregates Zeek logs by type before passing to Zeek Triage Agent

const zeekHits = $input.first().json.hits?.hits || [];

if (zeekHits.length === 0) {
  return [{ json: { source: 'zeek', logs: 'No Zeek logs in this time window.' } }];
}

// ── 1. CONN.LOG — aggregate by src+dst+port+proto ────────────
const connAgg = {};
for (const h of zeekHits.filter(h => h._source.container?.id === 'conn.log')) {
  const s = h._source;
  const key = `${s.source?.ip}->${s.destination?.ip}:${s.destination?.port}/${s.network?.transport}`;
  if (!connAgg[key]) {
    connAgg[key] = {
      src: s.source?.ip || '?',
      src_country: s.source?.geo?.country_iso_code || '',
      dst: s.destination?.ip || '?',
      dst_port: s.destination?.port || '?',
      proto: s.network?.transport || '?',
      service: s.network?.protocol || '',
      count: 0,
      total_bytes: 0,
      durations: [],
      first_seen: s['@timestamp'],
      last_seen: s['@timestamp'],
    };
  }
  const c = connAgg[key];
  c.count++;
  c.total_bytes += s.network?.bytes || 0;
  if (s.event?.duration) c.durations.push(s.event.duration);
  if (s['@timestamp'] < c.first_seen) c.first_seen = s['@timestamp'];
  if (s['@timestamp'] > c.last_seen)  c.last_seen  = s['@timestamp'];
}
const connLines = Object.values(connAgg).map(c => {
  const avgDur = c.durations.length
    ? (c.durations.reduce((a, b) => a + b, 0) / c.durations.length).toFixed(4)
    : 'N/A';
  const country = c.src_country ? `(${c.src_country})` : '';
  return `src=${c.src}${country} dst=${c.dst}:${c.dst_port} proto=${c.proto} service=${c.service} count=${c.count} bytes=${c.total_bytes} avg_dur=${avgDur}s first=${c.first_seen} last=${c.last_seen}`;
});

// ── 2. DNS.LOG — aggregate by src+query ──────────────────────
const dnsAgg = {};
for (const h of zeekHits.filter(h => h._source.container?.id === 'dns.log')) {
  const s = h._source;
  const z = s.zeek?.dns || s.dns || {};
  const key = `${s.source?.ip}|${z.query || '?'}`;
  if (!dnsAgg[key]) {
    dnsAgg[key] = {
      src: s.source?.ip || '?',
      query: z.query || '?',
      qtype: z.qtype_name || '?',
      rcodes: new Set(),
      count: 0,
      first_seen: s['@timestamp'],
      last_seen: s['@timestamp'],
    };
  }
  const d = dnsAgg[key];
  d.count++;
  if (z.rcode_name) d.rcodes.add(z.rcode_name);
  if (s['@timestamp'] < d.first_seen) d.first_seen = s['@timestamp'];
  if (s['@timestamp'] > d.last_seen)  d.last_seen  = s['@timestamp'];
}
const dnsLines = Object.values(dnsAgg).map(d =>
  `src=${d.src} query="${d.query}" type=${d.qtype} rcodes=${[...d.rcodes].join(',')} count=${d.count} first=${d.first_seen} last=${d.last_seen}`
);

// ── 3. HTTP.LOG — aggregate by src+dst+method+uri ────────────
const httpAgg = {};
for (const h of zeekHits.filter(h => h._source.container?.id === 'http.log')) {
  const s = h._source;
  const z = s.zeek?.http || s.http || {};
  const uri = z.uri || s.url?.original || '?';
  const method = z.method || '?';
  const key = `${s.source?.ip}->${s.destination?.ip}|${method}|${uri}`;
  if (!httpAgg[key]) {
    httpAgg[key] = {
      src: s.source?.ip || '?',
      dst: s.destination?.ip || '?',
      dst_port: s.destination?.port || '?',
      method,
      uri,
      status_codes: new Set(),
      user_agents: new Set(),
      count: 0,
      first_seen: s['@timestamp'],
      last_seen: s['@timestamp'],
    };
  }
  const hh = httpAgg[key];
  hh.count++;
  if (z.status_code) hh.status_codes.add(z.status_code);
  if (z.user_agent)  hh.user_agents.add(z.user_agent.substring(0, 50));
  if (s['@timestamp'] < hh.first_seen) hh.first_seen = s['@timestamp'];
  if (s['@timestamp'] > hh.last_seen)  hh.last_seen  = s['@timestamp'];
}
const httpLines = Object.values(httpAgg).map(h =>
  `src=${h.src} dst=${h.dst}:${h.dst_port} method=${h.method} uri="${h.uri}" status=[${[...h.status_codes].join(',')}] count=${h.count} ua="${[...h.user_agents][0] || '?'}" first=${h.first_seen} last=${h.last_seen}`
);

// ── 4. SSL.LOG — aggregate by src+dst+sni ────────────────────
const sslAgg = {};
for (const h of zeekHits.filter(h => h._source.container?.id === 'ssl.log')) {
  const s = h._source;
  const z = s.zeek?.ssl || s.tls || {};
  const sni = z.server_name || s.tls?.client?.server_name || '?';
  const key = `${s.source?.ip}->${s.destination?.ip}:${s.destination?.port}|${sni}`;
  if (!sslAgg[key]) {
    sslAgg[key] = {
      src: s.source?.ip || '?',
      dst: s.destination?.ip || '?',
      dst_port: s.destination?.port || '?',
      sni,
      version: z.version || s.tls?.version_protocol || '?',
      cert_valid: z.validation_status || '?',
      count: 0,
      first_seen: s['@timestamp'],
      last_seen: s['@timestamp'],
    };
  }
  const ss = sslAgg[key];
  ss.count++;
  if (s['@timestamp'] < ss.first_seen) ss.first_seen = s['@timestamp'];
  if (s['@timestamp'] > ss.last_seen)  ss.last_seen  = s['@timestamp'];
}
const sslLines = Object.values(sslAgg).map(ss =>
  `src=${ss.src} dst=${ss.dst}:${ss.dst_port} sni="${ss.sni}" version=${ss.version} cert_valid=${ss.cert_valid} count=${ss.count} first=${ss.first_seen} last=${ss.last_seen}`
);

// ── 5. NOTICE.LOG — aggregate by note type ───────────────────
const noticeAgg = {};
for (const h of zeekHits.filter(h => h._source.container?.id === 'notice.log')) {
  const s = h._source;
  const z = s.zeek?.notice || s.notice || {};
  const note = z.note || z.note_type || s.event?.action || '?';
  const src  = s.source?.ip || '?';
  const key  = `${src}|${note}`;
  if (!noticeAgg[key]) {
    noticeAgg[key] = {
      src,
      dst: s.destination?.ip || '?',
      note,
      msg: z.message || z.msg || '',
      count: 0,
      first_seen: s['@timestamp'],
      last_seen: s['@timestamp'],
    };
  }
  const n = noticeAgg[key];
  n.count++;
  if (s['@timestamp'] < n.first_seen) n.first_seen = s['@timestamp'];
  if (s['@timestamp'] > n.last_seen)  n.last_seen  = s['@timestamp'];
}
const noticeLines = Object.values(noticeAgg).map(n =>
  `src=${n.src} dst=${n.dst} note="${n.note}" msg="${n.msg.substring(0, 100)}" count=${n.count} first=${n.first_seen} last=${n.last_seen}`
);

// ── 6. WEIRD.LOG — aggregate by weird type ───────────────────
const weirdAgg = {};
for (const h of zeekHits.filter(h => h._source.container?.id === 'weird.log')) {
  const s = h._source;
  const z = s.zeek?.weird || s.weird || {};
  const name = z.name || '?';
  const key  = `${s.source?.ip}|${name}`;
  if (!weirdAgg[key]) {
    weirdAgg[key] = {
      src: s.source?.ip || '?',
      dst: s.destination?.ip || '?',
      name,
      addl: z.addl || '',
      count: 0,
      first_seen: s['@timestamp'],
      last_seen: s['@timestamp'],
    };
  }
  const w = weirdAgg[key];
  w.count++;
  if (s['@timestamp'] < w.first_seen) w.first_seen = s['@timestamp'];
  if (s['@timestamp'] > w.last_seen)  w.last_seen  = s['@timestamp'];
}
const weirdLines = Object.values(weirdAgg).map(w =>
  `src=${w.src} dst=${w.dst} weird="${w.name}" detail="${w.addl}" count=${w.count} first=${w.first_seen} last=${w.last_seen}`
);

// ── 7. KERBEROS.LOG — aggregate by src+client+service ────────
const kerbAgg = {};
for (const h of zeekHits.filter(h => h._source.container?.id === 'kerberos.log')) {
  const s = h._source;
  const z = s.zeek?.kerberos || s.kerberos || {};
  const key = `${s.source?.ip}|${z.client || '?'}|${z.service || '?'}`;
  if (!kerbAgg[key]) {
    kerbAgg[key] = {
      src: s.source?.ip || '?',
      dst: s.destination?.ip || '?',
      req_type: z.request_type || '?',
      client: z.client || '?',
      service: z.service || '?',
      success_count: 0,
      fail_count: 0,
      count: 0,
      first_seen: s['@timestamp'],
      last_seen: s['@timestamp'],
    };
  }
  const k = kerbAgg[key];
  k.count++;
  if (z.success === true)  k.success_count++;
  if (z.success === false) k.fail_count++;
  if (s['@timestamp'] < k.first_seen) k.first_seen = s['@timestamp'];
  if (s['@timestamp'] > k.last_seen)  k.last_seen  = s['@timestamp'];
}
const kerbLines = Object.values(kerbAgg).map(k =>
  `src=${k.src} dst=${k.dst} req_type=${k.req_type} client="${k.client}" service="${k.service}" success=${k.success_count} fail=${k.fail_count} count=${k.count} first=${k.first_seen} last=${k.last_seen}`
);

// ── 8. RDP.LOG — aggregate by src+dst ────────────────────────
const rdpAgg = {};
for (const h of zeekHits.filter(h => h._source.container?.id === 'rdp.log')) {
  const s = h._source;
  const z = s.zeek?.rdp || s.rdp || {};
  const key = `${s.source?.ip}->${s.destination?.ip}`;
  if (!rdpAgg[key]) {
    rdpAgg[key] = {
      src: s.source?.ip || '?',
      dst: s.destination?.ip || '?',
      dst_port: s.destination?.port || '?',
      cookie: z.cookie || '',
      success_count: 0,
      fail_count: 0,
      count: 0,
      first_seen: s['@timestamp'],
      last_seen: s['@timestamp'],
    };
  }
  const r = rdpAgg[key];
  r.count++;
  if (z.auth_success === true)  r.success_count++;
  if (z.auth_success === false) r.fail_count++;
  if (s['@timestamp'] < r.first_seen) r.first_seen = s['@timestamp'];
  if (s['@timestamp'] > r.last_seen)  r.last_seen  = s['@timestamp'];
}
const rdpLines = Object.values(rdpAgg).map(r =>
  `src=${r.src} dst=${r.dst}:${r.dst_port} cookie="${r.cookie}" auth_success=${r.success_count} auth_fail=${r.fail_count} count=${r.count} first=${r.first_seen} last=${r.last_seen}`
);

// ── 9. SMB_FILES.LOG — aggregate by src+dst+action ───────────
const smbAgg = {};
for (const h of zeekHits.filter(h => h._source.container?.id === 'smb_files.log')) {
  const s = h._source;
  const z = s.zeek?.smb_files || s.smb || {};
  const key = `${s.source?.ip}->${s.destination?.ip}|${z.action || '?'}`;
  if (!smbAgg[key]) {
    smbAgg[key] = {
      src: s.source?.ip || '?',
      dst: s.destination?.ip || '?',
      action: z.action || '?',
      paths: new Set(),
      count: 0,
      first_seen: s['@timestamp'],
      last_seen: s['@timestamp'],
    };
  }
  const sm = smbAgg[key];
  sm.count++;
  if (z.path) sm.paths.add(z.path);
  if (s['@timestamp'] < sm.first_seen) sm.first_seen = s['@timestamp'];
  if (s['@timestamp'] > sm.last_seen)  sm.last_seen  = s['@timestamp'];
}
const smbLines = Object.values(smbAgg).map(sm =>
  `src=${sm.src} dst=${sm.dst} action=${sm.action} paths=[${[...sm.paths].slice(0,3).join(',')}] count=${sm.count} first=${sm.first_seen} last=${sm.last_seen}`
);

// ── 10. DCE_RPC.LOG — aggregate by src+dst+endpoint ──────────
const rpcAgg = {};
for (const h of zeekHits.filter(h => h._source.container?.id === 'dce_rpc.log')) {
  const s = h._source;
  const z = s.zeek?.dce_rpc || s.dce_rpc || {};
  const key = `${s.source?.ip}->${s.destination?.ip}|${z.endpoint || '?'}|${z.operation || '?'}`;
  if (!rpcAgg[key]) {
    rpcAgg[key] = {
      src: s.source?.ip || '?',
      dst: s.destination?.ip || '?',
      endpoint: z.endpoint || '?',
      operation: z.operation || '?',
      count: 0,
      first_seen: s['@timestamp'],
      last_seen: s['@timestamp'],
    };
  }
  const rp = rpcAgg[key];
  rp.count++;
  if (s['@timestamp'] < rp.first_seen) rp.first_seen = s['@timestamp'];
  if (s['@timestamp'] > rp.last_seen)  rp.last_seen  = s['@timestamp'];
}
const rpcLines = Object.values(rpcAgg).map(rp =>
  `src=${rp.src} dst=${rp.dst} endpoint="${rp.endpoint}" operation="${rp.operation}" count=${rp.count} first=${rp.first_seen} last=${rp.last_seen}`
);

// ── Assemble final text ───────────────────────────────────────
const sections = [
  { name: 'notice',    lines: noticeLines },
  { name: 'weird',     lines: weirdLines  },
  { name: 'conn',      lines: connLines   },
  { name: 'dns',       lines: dnsLines    },
  { name: 'http',      lines: httpLines   },
  { name: 'ssl',       lines: sslLines    },
  { name: 'kerberos',  lines: kerbLines   },
  { name: 'rdp',       lines: rdpLines    },
  { name: 'smb_files', lines: smbLines    },
  { name: 'dce_rpc',   lines: rpcLines    },
].filter(sec => sec.lines.length > 0);

const zeekText = sections.length === 0
  ? 'No relevant Zeek logs in this time window.'
  : sections.map(sec =>
      `=== ${sec.name} (${sec.lines.length} unique flows) ===\n` + sec.lines.join('\n')
    ).join('\n\n');

return [{
  json: {
    source:      'zeek',
    event_group: 'all',
    logs:        zeekText,
  }
}];

// ── FORMAT SURICATA NODE ──────────────────────────────────────
// Aggregates Suricata alerts before passing to Suricata Triage Agent

const suricataHits = $input.first().json.hits?.hits || [];

if (suricataHits.length === 0) {
  return [{ json: { source: 'suricata', logs: 'No Suricata alerts in this time window.' } }];
}

// ── Aggregate by src_ip + dst_ip + dst_port + signature ──────
const agg = {};

for (const h of suricataHits) {
  const s = h._source;
  const signature = s.rule?.name || '?';
  const key = `${s.source?.ip}->${s.destination?.ip}:${s.destination?.port}|${signature}`;

  if (!agg[key]) {
    agg[key] = {
      src:        s.source?.ip      || '?',
      src_port:   s.source?.port    || '?',
      dst:        s.destination?.ip || '?',
      dst_port:   s.destination?.port || '?',
      proto:      s.network?.transport || '?',
      app_proto:  s.network?.protocol  || '',
      signature,
      category:   s.rule?.category  || '?',
      severity:   s.rule?.severity  || 99,
      count:      0,
      first_seen: s['@timestamp'],
      last_seen:  s['@timestamp'],
    };
  }

  const a = agg[key];
  a.count++;

  // Keep highest severity (lowest number = most severe in Suricata)
  if ((s.rule?.severity || 99) < a.severity) {
    a.severity = s.rule?.severity;
  }

  if (s['@timestamp'] < a.first_seen) a.first_seen = s['@timestamp'];
  if (s['@timestamp'] > a.last_seen)  a.last_seen  = s['@timestamp'];
}

// ── Sort by severity then count ───────────────────────────────
const sorted = Object.values(agg).sort((a, b) => {
  if (a.severity !== b.severity) return a.severity - b.severity;
  return b.count - a.count;
});

// ── Summary stats ─────────────────────────────────────────────
const totalAlerts    = suricataHits.length;
const uniqueFlows    = sorted.length;
const uniqueSrcIPs   = new Set(sorted.map(a => a.src)).size;
const criticalCount  = sorted.filter(a => a.severity === 1).length;
const highCount      = sorted.filter(a => a.severity === 2).length;
const mediumCount    = sorted.filter(a => a.severity === 3).length;

const summary = [
  `Total alerts: ${totalAlerts}`,
  `Unique src IPs: ${uniqueSrcIPs}`,
  `Unique flow+signature combos: ${uniqueFlows}`,
  `By severity — Critical(1): ${criticalCount}  High(2): ${highCount}  Medium(3): ${mediumCount}`,
].join(' | ');

// ── Format each aggregated alert ─────────────────────────────
const alertLines = sorted.map(a => {
  const appProto = a.app_proto ? ` app=${a.app_proto}` : '';
  return `src=${a.src} dst=${a.dst}:${a.dst_port} proto=${a.proto}${appProto} severity=${a.severity} count=${a.count} signature="${a.signature}" category="${a.category}" first=${a.first_seen} last=${a.last_seen}`;
});

const suricataText = `=== SUMMARY ===\n${summary}\n\n=== ALERTS (aggregated, sorted by severity) ===\n${alertLines.join('\n')}`;

// ── 在现有聚合代码末尾替换 return 语句 ──────────────────────

// 统计每个 dst_ip 被多少个不同 src_ip 攻击
const dstSrcCount = {};
for (const a of Object.values(agg)) {
  if (!dstSrcCount[a.dst]) dstSrcCount[a.dst] = new Set();
  dstSrcCount[a.dst].add(a.src);
}
const DDOS_THRESHOLD = 5;
const ddosTargets = new Set(
  Object.entries(dstSrcCount)
    .filter(([dst, srcs]) => srcs.size >= DDOS_THRESHOLD)
    .map(([dst]) => dst)
);

// 按事件分组
const eventMap = {};
for (const a of sorted) {
  let groupKey, groupType;
  if (ddosTargets.has(a.dst)) {
    groupKey  = `ddos-${a.dst}`;
    groupType = 'ddos';
  } else {
    groupKey  = `src-${a.src}`;
    groupType = 'single_source';
  }

  if (!eventMap[groupKey]) {
    eventMap[groupKey] = {
      group_type:   groupType,
      src_ips:      new Set(),
      dst_ips:      new Set(),
      min_severity: a.severity,
      alert_count:  0,
      alert_lines:  [],
    };
  }
  const ev = eventMap[groupKey];
  ev.src_ips.add(a.src);
  ev.dst_ips.add(a.dst);
  ev.alert_count += a.count;
  if (a.severity < ev.min_severity) ev.min_severity = a.severity;
  ev.alert_lines.push(
    `src=${a.src} dst=${a.dst}:${a.dst_port} proto=${a.proto} severity=${a.severity} count=${a.count} signature="${a.signature}" category="${a.category}" first=${a.first_seen} last=${a.last_seen}`
  );
}

// 每个事件输出一个 item
if (Object.keys(eventMap).length === 0) {
  return [{ json: { source: 'suricata', logs: 'No Suricata alerts.', event_group: 'none', needsEscalation: false } }];
}

return Object.entries(eventMap).map(([groupKey, ev]) => ({
  json: {
    source:        'suricata',
    event_group:   groupKey,
    group_type:    ev.group_type,
    src_ips:       [...ev.src_ips].join(', '),
    dst_ips:       [...ev.dst_ips].join(', '),
    src_ip_count:  ev.src_ips.size,
    dst_ip_count:  ev.dst_ips.size,
    alert_count:   ev.alert_count,
    min_severity:  ev.min_severity,
    needsEscalation: true,
    logs: `=== SURICATA ALERTS (${ev.group_type}) ===\n` +
          `src_ips: ${[...ev.src_ips].join(', ')} | dst_ips: ${[...ev.dst_ips].join(', ')} | total_alerts: ${ev.alert_count}\n\n` +
          ev.alert_lines.join('\n'),
  }
}));

const items = $input.all();

const zeekItem      = items.find(i => i.json.source === 'zeek');
const suricataItems = items.filter(i => i.json.source === 'suricata');
const zeekLogs      = zeekItem?.json.logs || 'No Zeek logs.';
const zeekLines     = zeekLogs.split('\n');

if (suricataItems.length === 0) {
  return [{ json: { needsEscalation: false, summary: 'All benign.' } }];
}

return suricataItems.map((item, idx) => {
  const s = item.json;

  // Extract all src IPs mentioned in indicators and reasoning
  const text = JSON.stringify(s.indicators || []) + ' ' + (s.reasoning || '');
  const ipMatches = text.match(/\b(?:\d{1,3}\.){3}\d{1,3}\b/g) || [];
  const uniqueIPs = [...new Set(ipMatches)];

  // Separate internal (10.x / 172.x / 192.168.x) from external IPs
  const internalRe = /^(10\.|172\.(1[6-9]|2\d|3[01])\.|192\.168\.)/;
  const srcIPs = uniqueIPs.filter(ip => !internalRe.test(ip));
  const dstIPs = uniqueIPs.filter(ip => internalRe.test(ip));

  // Find correlated Zeek lines for these IPs
  const relatedZeek = zeekLines.filter(line =>
    uniqueIPs.some(ip =>
      line.includes(`src=${ip}`) ||
      line.includes(`src=${ip}(`) ||
      line.includes(`dst=${ip}:`) ||
      line.includes(`dst=${ip} `)
    )
  );

  return {
    json: {
      event_id:        `EVT-${Date.now()}-${idx}`,
      source:          'suricata',
      verdict:         s.verdict,
      confidence:      s.confidence,
      indicators:      s.indicators,
      reasoning:       s.reasoning,
      src_ips:         srcIPs.join(', ') || 'unknown',
      dst_ips:         dstIPs.join(', ') || 'unknown',
      src_ip_count:    srcIPs.length,
      dst_ip_count:    dstIPs.length,
      alert_count:     s.alert_count || 1,
      group_type:      srcIPs.length > 0 ? 'single_source' : 'unknown',
      zeek_logs:       relatedZeek.length > 0 ? relatedZeek.join('\n') : 'No correlated Zeek logs.',
      needsEscalation: s.verdict === 'malicious' || s.verdict === 'suspicious',
      }
  };
});
